/*! Screeps: Automated Documentation Generator
 *  Generated by screeps-doc (https://github.com/screeps/screeps-doc)
 */

const path = require("path");
const fs = require("fs");
const { parse } = require("@screeps/shared/src/parse");
const { renderSource } = require("@screeps/shared/src/renderSource");
const { renderApi } = require("@screeps/shared/src/renderApi");
const { renderSidebar } = require("@screeps/shared/src/renderSidebar");
const { renderSection } = require("@screeps/shared/src/renderSection");
const { renderDocPage } = require("@screeps/shared/src/renderDocPage");
const { renderIndexPage } = require("@screeps/shared/src/renderIndexPage");

const DOCS_PATH = path.join(__dirname, "../docs");

function getModules(dirs) {
    return dirs.reduce((acc, dir) => {
        const srcDir = path.join(__dirname, dir);
        const mods = fs
            .readdirSync(srcDir)
            .filter((i) => i.endsWith(".js"))
            .map((i) => path.join(srcDir, i))
            .sort();
        return acc.concat(mods);
    }, []);
}

function generate() {
    const shared = require("@screeps/shared");
    const gameDir = path.join(__dirname, "../game");
    const sharedDir = path.join(__dirname, "../shared");
    const modules = getModules([gameDir, sharedDir]);
    const parsed = parse(modules, shared.externals);
    const docs = renderSource(parsed);
    const api = renderApi(docs);
    const sidebar = renderSidebar(docs);
    const sections = docs
        .map((item) => renderSection(item))
        .join("\n");
    const apiSidebar = renderSidebar(api);
    const apiSections = api
        .map((item) => renderSection(item))
        .join("\n");
    const indexPage = renderIndexPage(docs);

    const tableSection = docs.filter(i => i.type === "global").reduce((acc, i) => {
        acc += `<tr><td><a href="#${i.header}"><code>${i.header}</code></a></td><td>${i.description}</td></tr>`;
        return acc;
    }, "");

    const tableRotated = `<table id="table-rotated">
        <thead>
            <tr><th>Global</th><th>Description</th></tr>
        </thead>
        <tbody>
            ${tableSection}
        </tbody>
    </table>`;

    const indexHtml = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Screeps documentation</title>
    <link rel="icon" type="image/png" href="https://screeps.com/css/favicon.png">
</head>
<body>
    <div class="container">
        <h2>Quality & Metrics Reports</h2>
        <p>
            This repository is fully optimized with automated tools. Explore the generated
            reports below:
        </p>
        <div class="links">
            <a href="https://screeps.slack.com/"><img src="https://img.shields.io/badge/Slack-screeps.info-CC2B5E?style=flat&logo=slack" alt="Slack" /></a>
            <a href="https://github.com/screeps/screeps"><img src="https://img.shields.io/badge/GitHub-Screeps%20AI-9A9A9A?style=flat&logo=github" alt="GitHub" /></a>
            <a href="https://github.com/screeps/screeps_doc/actions/runs/1365348732"><img src="https://img.shields.io/badge/GitHub_Actions-Docs%20CI-9A9A9A?style=flat&logo=github-actions" alt="GitHub Actions" /></a>
        </div>
    </div>
</body>
</html>`;

    fs.writeFileSync(path.join(DOCS_PATH, "index.html"), indexPage);

    const apiHtml = renderDocPage(
        {
            title: "API — Screeps documentation",
            sidebar: apiSidebar,
            sections: apiSections,
            path: "api/index.html",
        },
        __dirname
    );
    fs.writeFileSync(path.join(DOCS_PATH, "api/index.html"), apiHtml);

    const tableHtml = renderDocPage(
        {
            title: "Globals — Screeps documentation",
            sidebar: sidebar,
            sections: `<main>${tableRotated}</main>`,
            path: "globals/index.html",
        },
        __dirname
    );
    fs.writeFileSync(path.join(DOCS_PATH, "globals/index.html"), tableHtml);
}

if (require.main === module) {
    generate();
}

module.exports = { generate };